// ==========================================
// ESP32: เชื่อมต่อ Wi-Fi และส่งสถานะผ่าน Serial Monitor
// เปลี่ยนชื่อ Wi-Fi, รหัสผ่าน และหมายเลขขา LED_PIN ด้านล่างได้ทันที
// ==========================================
#include <WiFi.h>

#define LED_PIN 2   // ขา Onboard LED สีน้ำเงินของบอร์ด ESP32 DevKit (GPIO 2)

const char* ssid     = "YOUR_WIFI_NAME";     // ระบุชื่อ Wi-Fi ของคุณ
const char* password = "YOUR_WIFI_PASSWORD"; // ระบุรหัสผ่าน Wi-Fi ของคุณ

void setup() {
  Serial.begin(115200); // ESP32 นิยมใช้ Baud rate 115200
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  Serial.println("\n--- ESP32 Connecting to Wi-Fi ---");
  Serial.print("Connecting to SSID: ");
  Serial.println(ssid);

  WiFi.mode(WIFI_STA); // ตั้งโหมดเป็น Wi-Fi Station
  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
    digitalWrite(LED_PIN, !digitalRead(LED_PIN)); // สลับไฟกะพริบระหว่างรอ
  }

  digitalWrite(LED_PIN, HIGH); // ติดค้างเมื่อต่อสำเร็จ
  Serial.println("\n>>> Wi-Fi Connected Successfully! <<<");
  Serial.print("ESP32 IP Address: ");
  Serial.println(WiFi.localIP());
  Serial.print("Signal Strength (RSSI): ");
  Serial.print(WiFi.RSSI());
  Serial.println(" dBm");
}

void loop() {
  // เชื่อมต่ออินเทอร์เน็ตแล้ว พร้อมส่งข้อมูลไปยัง Cloud หรือ MQTT ต่อไป
  delay(10000);
}
